1	/**
2	 * LanChat 前端交互逻辑。
3	 *
4	 * 全局状态:
5	 *   myInfo       - 本机信息 {uuid, name, ip, network, ws_port}
6	 *   onlinePeers  - 在线节点 Map<uuid, {name, ip}>
7	 *   contacts     - 历史联系人 Map<uuid, {name, ip, status, messages[]}>
8	 *   pendingReqs  - 待处理连接请求 Map<uuid, {name}>
9	 *   activeChats  - 活跃聊天 WS Map<uuid, WebSocket>
10	 *   currentChat  - 当前显示的聊天 uuid | null
11	 *   pendingMsgs  - 待确认消息 Map<msg_id, {content, uuid, timestamp}>
12	 */
13	
14	// ===== 全局状态 =====
15	let myInfo = null;
16	let onlinePeers = new Map();
17	let contacts = new Map();
18	let pendingRequests = new Map();
19	let activeChats = new Map();
20	let currentChat = null;
21	let pendingMessages = new Map();
22	let controlWs = null;
23	let reconnectTimer = null;
24	let reconnectAttempts = 0;
25	
26	// ===== DOM 引用 =====
27	const $ = (id) => document.getElementById(id);
28	const onlineList = $('online-list');
29	const onlineCount = $('online-count');
30	const pendingList = $('pending-list');
31	const pendingCount = $('pending-count');
32	const panelPending = $('panel-pending');
33	const contactsList = $('contacts-list');
34	const contactsCount = $('contacts-count');
35	const chatPlaceholder = $('chat-placeholder');
36	const chatContainer = $('chat-container');
37	const chatPeerName = $('chat-peer-name');
38	const chatPeerStatus = $('chat-peer-status');
39	const chatMessages = $('chat-messages');
40	const msgInput = $('msg-input');
41	const btnSend = $('btn-send');
42	const btnSendFile = $('btn-send-file');
43	const fileInput = $('file-input');
44	const btnCloseChat = $('btn-close-chat');
45	const btnDeleteContact = $('btn-delete-contact');
46	const btnScan = $('btn-scan');
47	const btnEditName = $('btn-edit-name');
48	const modalOverlay = $('modal-overlay');
49	const modalNameInput = $('modal-name-input');
50	const fileModalOverlay = $('file-modal-overlay');
51	const fileModalTitle = $('file-modal-title');
52	const fileModalBody = $('file-modal-body');
53	const fileModalButtons = $('file-modal-buttons');
54	
55	// ===== 初始化 =====
56	async function init() {
57	    await connectControl();
58	    bindEvents();
59	    startPolling();
60	}
61	
62	/** 连接控制 WebSocket */
63	async function connectControl() {
64	    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
65	    const url = `${protocol}//${location.host}/ws/control`;
66	
67	    return new Promise((resolve) => {
68	        controlWs = new WebSocket(url);
69	
70	        controlWs.onopen = () => {
71	            reconnectAttempts = 0;
72	            console.log('[Control] 已连接');
73	        };
74	
75	        controlWs.onmessage = (e) => {
76	            const msg = JSON.parse(e.data);
77	            handleControlMessage(msg);
78	            if (msg.type === 'init') resolve();
79	        };
80	
81	        controlWs.onclose = () => {
82	            console.log('[Control] 断开，尝试重连...');
83	            scheduleReconnect();
84	        };
85	
86	        controlWs.onerror = () => {};
87	    });
88	}
89	
90	/** 控制 WS 断开后指数退避重连 */
91	function scheduleReconnect() {
92	    if (reconnectTimer) return;
93	    const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000);
94	    const jitter = delay * (0.8 + Math.random() * 0.4);
95	    reconnectAttempts++;
96	    reconnectTimer = setTimeout(async () => {
97	        reconnectTimer = null;
98	        await connectControl();
99	    }, jitter);
100	}
101	
102	// ===== 事件绑定 =====
103	function bindEvents() {
104	    btnScan.addEventListener('click', () => fetchPeers());
105	    btnEditName.addEventListener('click', showEditNameModal);
106	    $('btn-modal-cancel').addEventListener('click', hideEditNameModal);
107	    $('btn-modal-save').addEventListener('click', saveName);
108	    modalNameInput.addEventListener('keydown', (e) => {
109	        if (e.key === 'Enter') saveName();
110	    });
111	    btnSend.addEventListener('click', sendCurrentMessage);
112	    msgInput.addEventListener('keydown', (e) => {
113	        if (e.key === 'Enter') sendCurrentMessage();
114	    });
115	    btnSendFile.addEventListener('click', () => fileInput.click());
116	    fileInput.addEventListener('change', onFileSelected);
117	    btnCloseChat.addEventListener('click', closeCurrentChat);
118	    btnDeleteContact.addEventListener('click', deleteCurrentContact);
119	
120	    // 手动连接：toggle 展开/收起
121	    const btnManualConnect = $('btn-manual-connect');
122	    const manualIpInput = $('manual-ip-input');
123	
124	    btnManualConnect.addEventListener('click', () => {
125	        const raw = manualIpInput.value.trim();
126	        if (!raw) return;
127	        let [ip, port] = raw.split(':');
128	        port = parseInt(port) || 50002;
129	        connectByIp(ip, port);
130	        manualIpInput.value = '';
131	        toggleManualConnect(); // 收起
132	    });
133	    manualIpInput.addEventListener('keydown', (e) => {
134	        if (e.key === 'Enter') btnManualConnect.click();
135	    });
136	}
137	
138	/** 展开/收起手动连接输入行（内联 onclick 和 JS 均可调用） */
139	function toggleManualConnect() {
140	    const row = $('manual-connect-row');
141	    const btn = $('btn-toggle-manual');
142	    if (!row || !btn) return;
143	    const visible = row.style.display !== 'none';
144	    row.style.display = visible ? 'none' : '';
145	    btn.textContent = visible ? '➕' : '✖';
146	    if (!visible) $('manual-ip-input').focus();
147	}
148	
149	// ===== 定时轮询 =====
150	function startPolling() {
151	    setInterval(fetchPeers, 3000);
152	    setInterval(fetchContacts, 5000);
153	    fetchPeers();
154	    fetchContacts();
155	}
156	
157	async function fetchPeers() {
158	    try {
159	        const resp = await fetch('/api/peers');
160	        const peers = await resp.json();
161	        updateOnlinePeers(peers);
162	    } catch (e) { /* ignore */ }
163	}
164	
165	async function fetchContacts() {
166	    try {
167	        const resp = await fetch('/api/contacts');
168	        const list = await resp.json();
169	        updateContacts(list);
170	    } catch (e) { /* ignore */ }
171	}
172	
173	// ===== 控制消息处理 =====
174	function handleControlMessage(msg) {
175	    const handlers = {
176	        init: handleInit,
177	        peer_online: handlePeerOnline,
178	        peer_offline: handlePeerOffline,
179	        incoming_connection: handleIncomingConnection,
180	        pending_update: handlePendingUpdate,
181	        connection_established: handleConnectionEstablished,
182	        peer_disconnected: handlePeerDisconnected,
183	        chat_message: handleIncomingMessage,
184	        message_ack: handleMessageAck,
185	        send_failed: handleSendFailed,
186	        incoming_file_request: handleIncomingFileRequest,
187	        file_request_response: handleFileRequestResponse,
188	        transfer_progress: handleTransferProgress,
189	        transfer_complete: handleTransferComplete,
190	        transfer_cancelled: handleTransferCancelled,
191	    };
192	    const handler = handlers[msg.type];
193	    if (handler) handler(msg);
194	}
195	
196	function handleInit(msg) {
197	    myInfo = msg;
198	    $('my-name-label').textContent = msg.name;
199	    $('my-ip-label').textContent = `IP: ${msg.ip}`;
200	    $('my-network-label').textContent = `网段: ${msg.network}`;
201	    // msg.token 是自己的 token，建立连接时需出示给对方后端验证
202	
203	    // 步骤1：先用 init 消息中的在线节点填充 onlinePeers（不等轮询）
204	    if (msg.online_peers && msg.online_peers.length > 0) {
205	        updateOnlinePeers(msg.online_peers);
206	    }
207	
208	    // 步骤2：加载历史联系人（此时 onlinePeers 已有数据，渲染时状态正确）
209	    if (msg.contacts && msg.contacts.length > 0) {
210	        updateContacts(msg.contacts);
211	    }
212	}
213	
214	function handlePeerOnline(msg) {
215	    // 过滤自己
216	    if (msg.uuid === myInfo.uuid) return;
217	    onlinePeers.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port, token: msg.token });
218	    // 如果历史联系人里有，更新在线状态
219	    if (contacts.has(msg.uuid)) {
220	        contacts.get(msg.uuid).status = 'online';
221	    }
222	    renderOnlineList();
223	    renderContactsList();
224	    updateChatHeaderStatus();
225	}
226	
227	function handlePeerOffline(msg) {
228	    onlinePeers.delete(msg.uuid);
229	    if (contacts.has(msg.uuid)) {
230	        contacts.get(msg.uuid).status = 'offline';
231	    }
232	    // 对应聊天 WS 断开
233	    const ws = activeChats.get(msg.uuid);
234	    if (ws) {
235	        ws.close();
236	        activeChats.delete(msg.uuid);
237	    }
238	    renderOnlineList();
239	    renderContactsList();
240	    updateChatHeaderStatus();
241	    addSystemMessage(msg.uuid, `${msg.name} 已下线`);
242	}
243	
244	function handleIncomingConnection(msg) {
245	    // 保存连接请求信息，包括 IP 和端口，以便同意后反向建立连接
246	    pendingRequests.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port });
247	    renderPendingList();
248	}
249	
250	function handlePendingUpdate(msg) {
251	    // count 可能在 pending 列表被其他地方修改后推送
252	    if (msg.count === 0) pendingRequests.clear();
253	}
254	
255	function handleConnectionEstablished(msg) {
256	    pendingRequests.delete(msg.uuid);
257	    // 加入联系人
258	    contacts.set(msg.uuid, {
259	        name: msg.name,
260	        ip: msg.ip,
261	        status: 'online',
262	        messages: [],
263	    });
264	    renderPendingList();
265	    renderContactsList();
266	    // 如果正在等对方的确认（主动发起方），打开聊天
267	    if (currentChat === msg.uuid || !currentChat) {
268	        openChat(msg.uuid);
269	    }
270	}
271	
272	function handlePeerDisconnected(msg) {
273	    activeChats.delete(msg.uuid);
274	    pendingRequests.delete(msg.uuid);
275	    renderPendingList();
276	    if (currentChat === msg.uuid) {
277	        updateChatHeaderStatus();
278	        addSystemMessage(msg.uuid, `${msg.name || '对方'} 已断开连接`);
279	    }
280	}
281	
282	function handleIncomingMessage(msg) {
283	    const uuid = msg.from;
284	    // 保存消息到联系人
285	    if (!contacts.has(uuid)) {
286	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
287	    }
288	    const contact = contacts.get(uuid);
289	    contact.messages.push({
290	        from: uuid,
291	        content: msg.content,
292	        msg_id: msg.msg_id,
293	        timestamp: msg.timestamp,
294	    });
295	    if (currentChat === uuid) {
296	        renderMessages(uuid);
297	    }
298	    // 当前没有聊天窗口时，自动打开
299	    if (!currentChat) {
300	        openChat(uuid);
301	    }
302	    renderContactsList();
303	}
304	
305	function handleMessageAck(msg) {
306	    pendingMessages.delete(msg.msg_id);
307	    if (currentChat) renderMessages(currentChat);
308	}
309	
310	function handleSendFailed(msg) {
311	    // 标记消息发送失败
312	    const pending = pendingMessages.get(msg.msg_id);
313	    if (pending) {
314	        pending.status = 'failed';
315	        pendingMessages.set(msg.msg_id, pending);
316	    }
317	    if (currentChat) renderMessages(currentChat);
318	}
319	
320	// ===== 文件传输消息处理 =====
321	
322	function handleIncomingFileRequest(msg) {
323	    showFileRequestModal(msg);
324	}
325	
326	function handleFileRequestResponse(msg) {
327	    if (msg.accepted) {
328	        console.log(`[Transfer] 对方接受传输: ${msg.transfer_id}`);
329	    } else {
330	        showToast('对方拒绝了文件传输');
331	    }
332	}
333	
334	function handleTransferProgress(msg) {
335	    // 更新传输进度（可在聊天区或侧边栏展示进度条）
336	    console.log(`[Transfer] 进度: ${msg.received_bytes}/${msg.total_bytes}`);
337	}
338	
339	function handleTransferComplete(msg) {
340	    showToast(`文件接收完成: ${msg.file_name}`);
341	    addSystemMessage(currentChat, `文件 ${msg.file_name} 接收完成 ✓`);
342	}
343	
344	function handleTransferCancelled(msg) {
345	    showToast('对方取消了文件传输');
346	    addSystemMessage(currentChat, '文件传输已取消');
347	}
348	
349	// ===== 在线列表渲染 =====
350	function updateOnlinePeers(peers) {
351	    onlinePeers.clear();
352	    for (const p of peers) {
353	        // 过滤自己
354	        if (p.uuid === myInfo.uuid) continue;
355	        // 保存 token，用于建立连接时出示给对方后端验证
356	        onlinePeers.set(p.uuid, { name: p.name, ip: p.ip, ws_port: p.ws_port, token: p.token });
357	    }
358	    renderOnlineList();
359	    // 同时刷新联系人列表的状态（在线/离线圆点）
360	    renderContactsList();
361	    updateChatHeaderStatus();
362	}
363	
364	function renderOnlineList() {
365	    onlineCount.textContent = onlinePeers.size;
366	    if (onlinePeers.size === 0) {
367	        onlineList.innerHTML = '<div class="empty-hint">暂无在线用户</div>';
368	        return;
369	    }
370	    onlineList.innerHTML = '';
371	    for (const [uuid, peer] of onlinePeers) {
372	        const div = document.createElement('div');
373	        div.className = `item${currentChat === uuid ? ' active' : ''}`;
374	        div.innerHTML = `
375	            <span class="dot online"></span>
376	            <div class="info">
377	                <div class="name">${esc(peer.name)}</div>
378	                <div class="sub">${esc(peer.ip)}</div>
379	            </div>`;
380	        div.addEventListener('click', () => connectToPeer(uuid, peer.name, peer.ip));
381	        onlineList.appendChild(div);
382	    }
383	}
384	
385	// ===== 待处理请求列表渲染 =====
386	function renderPendingList() {
387	    if (pendingRequests.size === 0) {
388	        panelPending.style.display = 'none';
389	        return;
390	    }
391	    panelPending.style.display = '';
392	    pendingCount.textContent = pendingRequests.size;
393	    pendingList.innerHTML = '';
394	    for (const [uuid, req] of pendingRequests) {
395	        const div = document.createElement('div');
396	        div.className = 'item';
397	        div.innerHTML = `
398	            <span class="dot pending"></span>
399	            <div class="info"><div class="name">${esc(req.name)}</div></div>
400	            <div class="actions">
401	                <button class="btn-accept" data-uuid="${uuid}">同意</button>
402	                <button class="btn-reject" data-uuid="${uuid}">拒绝</button>
403	            </div>`;
404	        div.querySelector('.btn-accept').addEventListener('click', (e) => {
405	            e.stopPropagation();
406	            respondConnection(uuid, true);
407	        });
408	        div.querySelector('.btn-reject').addEventListener('click', (e) => {
409	            e.stopPropagation();
410	            respondConnection(uuid, false);
411	        });
412	        pendingList.appendChild(div);
413	    }
414	}
415	
416	async function respondConnection(uuid, accepted) {
417	    controlWs.send(JSON.stringify({
418	        type: 'connection_response',
419	        to_uuid: uuid,
420	        accepted: accepted,
421	    }));
422	    pendingRequests.delete(uuid);
423	    renderPendingList();
424	    if (accepted) {
425	        // 保存联系人信息并打开聊天窗口
426	        // 注意：消息发送走 A→B后端的 chat WS（双向），B→A 走 B后端的 active_chats[A] 回传同一 WS
427	        const peer = onlinePeers.get(uuid) || { name: 'Unknown', ip: '' };
428	        contacts.set(uuid, { name: peer.name, ip: peer.ip, status: 'online', messages: [] });
429	        openChat(uuid);
430	    }
431	}
432	
433	// ===== 历史联系人列表渲染 =====
434	function updateContacts(list) {
435	    for (const c of list) {
436	        // 过滤自己
437	        if (c.uuid === myInfo.uuid) continue;
438	        if (!contacts.has(c.uuid)) {
439	            contacts.set(c.uuid, {
440	                name: c.name,
441	                ip: c.ip,
442	                status: c.status,
443	                messages: [],
444	            });
445	        } else {
446	            contacts.get(c.uuid).status = c.status;
447	            contacts.get(c.uuid).name = c.name || contacts.get(c.uuid).name;
448	            contacts.get(c.uuid).ip = c.ip || contacts.get(c.uuid).ip;
449	        }
450	    }
451	    renderContactsList();
452	    updateChatHeaderStatus();
453	}
454	
455	function renderContactsList() {
456	    const list = Array.from(contacts.entries())
457	        .sort((a, b) => {
458	            // 在线排前面，同状态按名字排序
459	            if (a[1].status !== b[1].status) return a[1].status === 'online' ? -1 : 1;
460	            return a[1].name.localeCompare(b[1].name);
461	        });
462	
463	    contactsCount.textContent = list.length;
464	    if (list.length === 0) {
465	        contactsList.innerHTML = '<div class="empty-hint">暂无历史联系人</div>';
466	        return;
467	    }
468	
469	    contactsList.innerHTML = '';
470	    for (const [uuid, contact] of list) {
471	        const div = document.createElement('div');
472	        div.className = `item${currentChat === uuid ? ' active' : ''}`;
473	        // 用实时在线列表判断状态，与点击行为保持一致
474	        const isOnline = onlinePeers.has(uuid);
475	        const dotClass = isOnline ? 'online' : 'offline';
476	        const statusText = isOnline ? '' : ' (离线)';
477	        div.innerHTML = `
478	            <span class="dot ${dotClass}"></span>
479	            <div class="info">
480	                <div class="name">${esc(contact.name)}${statusText}</div>
481	                <div class="sub">${esc(contact.ip)}</div>
482	            </div>`;
483	        div.addEventListener('click', () => {
484	            // 用实时在线列表判断（与 updateChatHeaderStatus 数据源一致）
485	            if (onlinePeers.has(uuid)) {
486	                // 在线 → 自动发送连接请求
487	                connectToPeer(uuid, contact.name, contact.ip);
488	            } else {
489	                // 离线 → 提示用户，但仍然加载历史聊天记录
490	                showToast('对方不在线');
491	                openChat(uuid);
492	            }
493	        });
494	        // 右键删除
495	        div.addEventListener('contextmenu', (e) => {
496	            e.preventDefault();
497	            if (confirm(`确定删除联系人 ${contact.name} 及聊天记录？`)) {
498	                deleteContact(uuid);
499	            }
500	        });
501	        contactsList.appendChild(div);
502	    }
503	}
504	
505	async function deleteContact(uuid) {
506	    try {
507	        await fetch(`/api/contacts/${uuid}`, { method: 'DELETE' });
508	    } catch (e) { /* ignore */ }
509	    contacts.delete(uuid);
510	    if (currentChat === uuid) closeCurrentChat();
511	    renderContactsList();
512	}
513	
514	// ===== 连接对端 / 打开聊天 =====
515	
516	/**
517	 * 主动发起与对端的 WebSocket 连接。
518	 * 流程: 连接 ws://peer_ip:ws_port/ws/chat → 发 connect_request（带 token）→ 等 connect_accepted
519	 */
520	async function connectToPeer(uuid, name, ip) {
521	    // 如果已有活跃连接，直接打开聊天
522	    if (activeChats.has(uuid)) {
523	        openChat(uuid);
524	        return;
525	    }
526	
527	    // 获取对端 ws_port（从在线节点列表）
528	    const peer = onlinePeers.get(uuid);
529	    if (!peer) {
530	        showToast('对方不在线');
531	        return;
532	    }
533	
534	    openChat(uuid); // 先打开聊天窗口，显示"连接中..."
535	
536	    // 连接前先刷新自己的 token（token 每3秒更新，避免用过期的）
537	    try {
538	        const resp = await fetch('/api/me');
539	        const me = await resp.json();
540	        myInfo.token = me.token;
541	    } catch (e) { /* 刷新失败则用现有 token */ }
542	
543	    try {
544	        const peerPort = peer.ws_port || 50002;
545	        const wsUrl = `ws://${peer.ip}:${peerPort}/ws/chat`;
546	        const ws = new WebSocket(wsUrl);
547	
548	        ws.onopen = () => {
549	            // 发送连接请求，带上自己的 token 给对方后端验证
550	            // 对方通过 UDP 广播收到了我的 token，验证是否匹配
551	            ws.send(JSON.stringify({
552	                type: 'connect_request',
553	                uuid: myInfo.uuid,
554	                name: myInfo.name,
555	                token: myInfo.token,
556	                ip: myInfo.ip,
557	                ws_port: myInfo.ws_port,
558	            }));
559	        };
560	
561	        ws.onmessage = (e) => {
562	            const msg = JSON.parse(e.data);
563	            if (msg.type === 'connect_accepted') {
564	                activeChats.set(uuid, ws);
565	                setupPeerMessageHandler(uuid, ws);
566	                addSystemMessage(uuid, '连接已建立');
567	                // 通知自己后端保存联系人（对方后端已保存，自己后端也需要记录）
568	                controlWs.send(JSON.stringify({
569	                    type: 'save_contact',
570	                    uuid: uuid,
571	                    name: name,
572	                    ip: ip,
573	                    ws_port: peer.ws_port || 50002,
574	                }));
575	            } else if (msg.type === 'connect_rejected') {
576	                ws.close();
577	                const reason = msg.reason === 'invalid_token' ? 'Token 验证失败，请稍后重试' : '对方拒绝了连接请求';
578	                addSystemMessage(uuid, reason);
579	                showToast(reason);
580	            }
581	        };
582	
583	        ws.onclose = () => {
584	            activeChats.delete(uuid);
585	            if (currentChat === uuid) {
