938	        type: 'file_request',
939	        transfer_id: transferId,
940	        file_name: file.name,
941	        file_size: file.size,
942	        chunk_size: CHUNK_SIZE,
943	        total_chunks: totalChunks,
944	        resume: false,
945	    }));
946	
947	    // 等待 file_response（通过 control ws 回调继续）
948	    addSystemMessage(uuid, `发送文件: ${file.name} (${formatSize(file.size)})`);
949	
950	    // 开始发送分片
951	    window._pendingFileTransfers = window._pendingFileTransfers || {};
952	    window._pendingFileTransfers[transferId] = { file, uuid, totalChunks, CHUNK_SIZE, transferId, currentChunk: 0 };
953	
954	    // 等待对方响应后开始发送分片
955	    const originalHandler = handleFileRequestResponse;
956	    const onceHandler = (msg) => {
957	        if (msg.transfer_id === transferId) {
958	            if (msg.accepted) {
959	                startChunkUpload(transferId);
960	            }
961	            // 恢复原始处理器
962	            window._fileResponseHandler = originalHandler;
