972	    if (window._fileResponseHandler) {
973	        window._fileResponseHandler(msg);
974	    } else if (msg.accepted) {
975	        // 查找匹配的传输并开始上传
976	        const transfers = window._pendingFileTransfers || {};
977	        for (const [tid, t] of Object.entries(transfers)) {
978	            if (!t.started) {
