987	async function startChunkUpload(transferId) {
988	    const t = window._pendingFileTransfers?.[transferId];
989	    if (!t) return;
990	
991	    const peer = onlinePeers.get(t.uuid);
992	    if (!peer) {
993	        showToast('对方不在线，无法发送文件');
994	        return;
995	    }
996	
997	    const file = t.file;
998	    const CHUNK_SIZE = t.CHUNK_SIZE;
999	    const totalChunks = t.totalChunks;
1000	
1001	    for (let i = t.currentChunk; i < totalChunks; i++) {
1002	        const start = i * CHUNK_SIZE;
1003	        const end = Math.min(start + CHUNK_SIZE, file.size);
1004	        const blob = file.slice(start, end);
1005	        const dataB64 = await readAsBase64(blob);
1006	
1007	        let retries = 0;
1008	        let success = false;
1009	
1010	        while (retries < 3 && !success) {
1011	            try {
1012	                const peerPort = peer.ws_port || 50002;
1013	            const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1014	                    method: 'POST',
1015	                    headers: { 'Content-Type': 'application/json' },
1016	                    body: JSON.stringify({
1017	                        transfer_id: transferId,
1018	                        chunk_index: i,
1019	                        data: dataB64,
1020	                    }),
1021	                });
1022	                if (resp.ok) {
1023	                    success = true;
1024	                    t.currentChunk = i + 1;
1025	                } else {
1026	                    retries++;
1027	                }
1028	            } catch (e) {
1029	                retries++;
1030	            }
1031	        }
1032	
1033	        if (!success) {
1034	            addSystemMessage(t.uuid, '文件传输中断，等待对方重新上线');
1035	            return; // 传输暂停，等待后续续传
1036	        }
1037	    }
1038	
1039	    // 完成
1040	    try {
1041	        const peerPort = peer.ws_port || 50002;
1042	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
1043	            method: 'POST',
1044	            headers: { 'Content-Type': 'application/json' },
1045	            body: JSON.stringify({ transfer_id: transferId }),
1046	        });
1047	        addSystemMessage(t.uuid, `文件 ${file.name} 发送完成 ✓`);
1048	    } catch (e) {
1049	        addSystemMessage(t.uuid, '文件传输完成确认失败');
1050	    }
1051	
1052	    delete window._pendingFileTransfers?.[transferId];
1053	}
